// === PARSE PERINTAH "scan ..." DARI PAYLOAD WHATSAPP CLOUD API ===

const item = $input.first().json;

// 1. Ekstraksi aman untuk pesan dan nomor pengirim dari WhatsApp Cloud API
const msgObj = item.messages?.[0];
const pesanAsli = msgObj?.text?.body || item.message || item.text || item.body || '';
const nomorPengirim = msgObj?.from || item.from || item.phone || item.sender || '';

// 2. Base URL
const BASE_URL = 'https://claudescalping.vercel.app'.replace(/\/+$/, '');
const SCALPING_URL = 'https://claudescalping.vercel.app'.replace(/\/+$/, ''); // URL khusus scalping

const pesan = String(pesanAsli).trim();
const pesanLower = pesan.toLowerCase();

// Teks petunjuk yang dirapikan untuk WhatsApp
const teksPetunjuk =
  "📖 *PANDUAN PERINTAH BOT SCANNER*\n" +
  "━━━━━━━━━━━━━━━━━━━━━━━━━\n\n" +
  "🔹 *scan BBCA*\n" +
  "└ _Analisis swing BBCA_\n\n" +
  "🔹 *scan BBCA gorengan*\n" +
  "└ _Analisis momentum gorengan BBCA_\n\n" +
  "🔹 *scan BBCA scalping*\n" +
  "└ _Analisis scalping / intraday BBCA_\n\n" +
  "🔹 *scan BBCA bpjs [hari] [pjual] [pbeli]*\n" +
  "└ _Range pagi-sore (Cth: scan BBCA bpjs 30 0.3 0.5)_\n\n" +
  "🔹 *scan BBCA beli-pagi [hari] [pbeli] [pjual]*\n" +
  "└ _BPJS asli: beli pagi, jual sore (Cth: scan BBCA beli-pagi 20 0.3 0.5)_\n\n" +
  "🔹 *scan BBCA strategi*\n" +
  "└ _Rekomendasi strategi paling cocok (6 strategi diskor)_\n\n" +
  "🔹 *scan validasi BBCA*\n" +
  "└ _Validasi skor strategi vs performa backtest historis_\n\n" +
  "🔹 *scan rekomendasi Bank*\n" +
  "└ _Saham terbaik per strategi di sektor (Bank, Coal, Real Estate, dll)_\n\n" +
  "🔹 *scan screener swing*\n" +
  "└ _Screener seluruh watchlist bluechip_\n\n" +
  "🔹 *scan screener gorengan*\n" +
  "└ _Screener seluruh watchlist gorengan_\n\n" +
  "🔹 *scan screener scalping big*\n" +
  "└ _Screener scalping tanpa pagination_\n\n" +
  "🔹 *scan screener scalping [offset] [limit]*\n" +
  "└ _Screener scalping (Cth: scan screener scalping 0 20)_\n\n" +
  "🔹 *scan backtest BBCA* atau *scan backtest BBCA 3*\n" +
  "└ _Backtest swing (default 2 tahun, atau custom)_\n\n" +
  "🔹 *scan backtest BBCA gorengan*\n" +
  "└ _Backtest gorengan_\n\n" +
  "🔹 *scan backtest BBCA beli-pagi*\n" +
  "└ _Backtest BPJS (beli pagi jual sore)_\n\n" +
  "🔹 *DAFTAR SEKTOR YANG BISA DI-SCAN*\n" +
  "└ _Ketik: scan rekomendasi [kata kunci]_\n" +
  "└ _Contoh: scan rekomendasi Bank_\n" +
  "━━━━━━━━━━━━━━━━━━━━━━━━━\n" +
  "🏦 *Keuangan*: Bank (48) | Insurance (21) | Credit (14) | Capital Markets (6) | Asset (8)\n" +
  "\n" +
  "⛽ *Energi & Tambang*: Coal (32) | Oil & Gas (22) | Chemicals (26) | Mining (19) | Steel (7) | Gold (4) | Aluminum (3)\n" +
  "\n" +
  "🏗️ *Properti & Konstruksi*: Real Estate (87) | Construction (33) | Engineering (28) | Building (21) | Utilities (12)\n" +
  "\n" +
  "🚢 *Industri & Logistik*: Marine Shipping (33) | Packaging (19) | Trucking (9) | Logistics (8) | Conglomerates (6) | Railroads (4) | Airlines (2) | Airports (2)\n" +
  "\n" +
  "🛒 *Konsumen*: Food (47) | Farm (40) | Retail (19) | Lodging (19) | Auto (18) | Entertainment (13) | Restaurants (11) | Beverages (10) | Textile (10) | Household (9) | Apparel (7) | Travel (5) | Leisure (5) | Tobacco (3) | Grocery (3)\n" +
  "\n" +
  "💻 *Teknologi & Telekomunikasi*: Telecom (19) | Software (10) | Technology (9) | Internet (6) | Broadcasting (6) | Electronics (5)\n" +
  "\n" +
  "💊 *Kesehatan*: Medical (24) | Drug Manufacturers (6) | Pharmaceutical (3)\n" +
  "\n" +
  "🏬 *Lainnya*: Department Stores (7) | Waste (3) | Rental (5) | Education (2)\n" +
  "\n" +
  "🔹 *scan market*\n" +
  "└ _Cek kondisi IHSG_\n\n" +
  "🔔 *NOTIFIKASI PAGI OTOMATIS*\n" +
  "└ _Most Active + Rekomendasi Intraday dikirim tiap 07:00 WIB (Senin-Jumat)_\n\n" +

  "└ _Cek kondisi IHSG_";

function hasilTidakValid(alasan) {
  return [{
    json: {
      valid: false,
      url: '',
      aksi: '',
      ticker: '',
      from: nomorPengirim,
      alasan: alasan || teksPetunjuk
    }
  }];
}

// Cek apakah diawali kata "scan"
if (!pesanLower.startsWith('scan')) {
  return hasilTidakValid('Pesan tidak diawali kata "scan", diabaikan.');
}

const sisaPesan = pesan.slice(4).trim();
const bagian = sisaPesan.split(/\s+/).filter(Boolean);

// Jika user hanya mengetik "scan" saja
if (bagian.length === 0) {
  return hasilTidakValid(teksPetunjuk);
}

const kata1 = bagian[0].toLowerCase();

// Jika user mengetik "scan petunjuk", "scan help", atau "scan bantuan"
if (kata1 === 'petunjuk' || kata1 === 'help' || kata1 === 'bantuan') {
  return hasilTidakValid(teksPetunjuk);
}

let aksi = '';
let url = '';
let ticker = '';

// Routing URL berdasarkan perintah
if (kata1 === 'market') {
  aksi = 'market';
  url = `${BASE_URL}/v1/market/status`;
} else if (kata1 === 'most-active' || kata1 === 'top-value' || kata1 === 'top-gainer' || kata1 === 'top-loser') {
  // scan most-active [n] | top-value [n] | top-gainer [n] | top-loser [n]
  const jenisPasar = { 'most-active': 'active', 'top-value': 'value', 'top-gainer': 'gainer', 'top-loser': 'loser' }[kata1];
  const limPasar = /^\d{1,2}$/.test(bagian[1] || '') ? Math.min(Math.max(parseInt(bagian[1], 10), 1), 30) : 10;
  aksi = 'pasar_' + jenisPasar;
  url = `${BASE_URL}/v1/pasar/most-active?jenis=${jenisPasar}&limit=${limPasar}`;

} else if (kata1 === 'intraday') {
  // scan intraday [n] -> rekomendasi saham likuid untuk strategi intraday
  const nIntraday = /^\d{1,2}$/.test(bagian[1] || '') ? Math.min(Math.max(parseInt(bagian[1], 10), 1), 15) : 5;
  aksi = 'rekomendasi_intraday';
  url = `${BASE_URL}/v1/rekomendasi/intraday?n=${nIntraday}`;

} else if (kata1 === 'rekomendasi') {
  // scan rekomendasi Bank | Coal | "Real Estate" | dsb
  // Angka opsional di akhir = max_saham (cth: "scan rekomendasi Bank 20").
  // Tanda kutip dihapus supaya "Real Estate" dikenali sebagai Real Estate.
  let kataSektor = bagian.slice(1).map(w => w.replace(/["']/g, '')).join(' ');
  let maksSaham = 10;
  const angka = kataSektor.match(/\s+(\d{1,2})$/);
  if (angka) {
    maksSaham = Math.min(Math.max(parseInt(angka[1], 10), 1), 30);
    kataSektor = kataSektor.replace(/\s+\d{1,2}$/, '');
  }
  kataSektor = kataSektor.trim();
  // scan rekomendasi intraday [n] -> rekomendasi saham likuid untuk strategi intraday
  if (kataSektor.toLowerCase().split(/\s+/)[0] === 'intraday') {
    // maksSaham sudah diparse dari angka di belakang kataSektor sebelumnya
    const nIntraday = Math.min(Math.max(parseInt(maksSaham, 10) || 5, 1), 15);
    return [{ json: { valid: true, aksi: 'rekomendasi_intraday', url: `${BASE_URL}/v1/rekomendasi/intraday?n=${nIntraday}`, ticker: '', from: nomorPengirim } }];
  }
  if (!kataSektor) {
    return hasilTidakValid('Format: *scan rekomendasi [SEKTOR]* — contoh: *scan rekomendasi Bank*, *scan rekomendasi Coal*, *scan rekomendasi "Real Estate"*.');
  }

  // Daftar kata kunci sektor yang dikenali (lowercase). Dipakai untuk membedakan
  // 'scan rekomendasi Bank' (sektor) vs 'scan rekomendasi BBRI' (satu saham).
  const KATA_KUNCI_SEKTOR = [
    'bank', 'insurance', 'credit', 'capital markets', 'asset',
    'coal', 'oil & gas', 'chemicals', 'mining', 'steel', 'gold', 'aluminum',
    'real estate', 'construction', 'engineering', 'building', 'utilities',
    'marine shipping', 'packaging', 'trucking', 'logistics', 'conglomerates',
    'railroads', 'airlines', 'airports',
    'food', 'farm', 'retail', 'lodging', 'auto', 'entertainment', 'restaurants',
    'beverages', 'textile', 'household', 'apparel', 'travel', 'leisure',
    'tobacco', 'grocery',
    'telecom', 'software', 'technology', 'internet', 'broadcasting', 'electronics',
    'medical', 'drug manufacturers', 'pharmaceutical',
    'department stores', 'waste', 'rental', 'education'
  ];

  const sektorDikenal = KATA_KUNCI_SEKTOR.includes(kataSektor.toLowerCase());
  // Ticker = 2-5 huruf/angka (mis. BBRI, TLKM, AADI, BAYU). Kalau keyword tidak
  // cocok sektor mana pun tapi berbentuk ticker → user sebenarnya ingin analisis
  // SATU saham. Fallback otomatis supaya tidak error 404 membingungkan.
  const terlihatTicker = !sektorDikenal && /^[A-Z0-9]{2,5}$/.test(kataSektor.toUpperCase());

  if (terlihatTicker) {
    aksi = 'analisis_strategi_gabungan';
    url = `${SCALPING_URL}/v1/analisis/strategi-gabungan/${kataSektor.toUpperCase()}`;
  } else {
    aksi = 'rekomendasi_sektor';
    // backtest=false default: response lebih cepat & tidak menambah puluhan
    // request Yahoo (rate-limit). max_saham default 10 (bukan 15) biar beban
    // lebih ringan di serverless. Keduanya bisa di-override via API langsung.
    url = `${SCALPING_URL}/v1/rekomendasi/sektor?industri=${encodeURIComponent(kataSektor)}&max_saham=${maksSaham}&backtest=false`;
  }

} else if (kata1 === 'validasi') {
  ticker = (bagian[1] || '').toUpperCase();
  if (!ticker) {
    return hasilTidakValid('Format: *scan validasi [TICKER]* — bandingkan skor strategi vs performa backtest.');
  }
  aksi = 'validasi_strategi';
  url = `${SCALPING_URL}/v1/backtest/validasi-strategi/${ticker}`;

} else if (kata1 === 'screener') {
  const jenis = (bagian[1] || 'swing').toLowerCase();

  if (jenis === 'gorengan') {
    aksi = 'screener_gorengan';
    url = `${BASE_URL}/v1/screener/gorengan-momentum`;
  } else if (jenis === 'scalping') {
    aksi = 'screener_scalping';

    // Cek apakah perintahnya "scan screener scalping big"
    const parameter = (bagian[2] || '').toLowerCase();

    if (parameter === 'big') {
      // Jika "big", arahkan ke endpoint yang sesuai
      url = `${SCALPING_URL}/v1/screener/fast-intraday`;
    } else {
      // Jika bukan "big", asumsikan itu format offset dan limit
      const offset = parameter || '0';
      const limit = bagian[3] || '20'; // Default limit
      url = `${SCALPING_URL}/v1/screener/fast-intraday/semua-saham?offset=${offset}&limit=${limit}`;
    }
  } else {
    aksi = 'screener_swing';
    url = `${BASE_URL}/v1/screener/swing-dividen`;
  }

} else if (kata1 === 'backtest') {
  ticker = (bagian[1] || '').toUpperCase();
  if (!ticker) {
    return hasilTidakValid('Format: *scan backtest [TICKER] [tahun opsional]* | *scan backtest [TICKER] gorengan* | *scan backtest [TICKER] beli-pagi*');
  }

  const opsiKetiga = (bagian[2] || '').toLowerCase();
  if (opsiKetiga === 'gorengan') {
    aksi = 'backtest_gorengan';
    url = `${BASE_URL}/v1/backtest/gorengan/${ticker}`;
  } else if (opsiKetiga === 'beli-pagi') {
    // Backtest BPJS asli (Beli Pagi Jual Sore)
    aksi = 'backtest_bpjs';
    url = `${SCALPING_URL}/v1/backtest/bpjs/${ticker}`;
  } else {
    const tahun = /^[0-9]+$/.test(opsiKetiga) ? opsiKetiga : '2';
    aksi = 'backtest_swing';
    url = `${BASE_URL}/v1/backtest/swing/${ticker}?tahun=${tahun}`;
  }

} else {
  // Format: "scan [TICKER]", "scan [TICKER] gorengan", "scan [TICKER] scalping",
  //         "scan [TICKER] bpjs", "scan [TICKER] beli-pagi", "scan [TICKER] strategi"
  ticker = bagian[0].toUpperCase();
  const jenis = (bagian[1] || 'swing').toLowerCase();

  if (jenis === 'gorengan') {
    aksi = 'analisis_gorengan';
    url = `${BASE_URL}/v1/analisis/gorengan/${ticker}`;
  } else if (jenis === 'scalping') {
    aksi = 'analisis_scalping';
    url = `${SCALPING_URL}/v1/analisis/fast-intraday/${ticker}`;
  } else if (jenis === 'strategi') {
    // Rekomendasi strategi gabungan (6 strategi diskor sekaligus)
    aksi = 'analisis_strategi_gabungan';
    url = `${SCALPING_URL}/v1/analisis/strategi-gabungan/${ticker}`;
  } else if (jenis === 'beli-pagi') {
    // BPJS asli: BELI pagi, JUAL sore (kebalikan dari "bpjs" = range pagi-sore)
    const windowHari = bagian[2] || '20';
    const persentilBeli = bagian[3] || '0.3';
    const persentilJual = bagian[4] || '0.5';
    aksi = 'analisis_bpjs';
    url = `${SCALPING_URL}/v1/analisis/bpjs/${ticker}?window_hari=${windowHari}&persentil_beli=${persentilBeli}&persentil_jual=${persentilJual}`;
  } else if (jenis === 'bpjs') {
    // Kebiasaan lama: "bpjs" = range pagi-sore (JUAL pagi, BELI sore)
    const windowHari = bagian[2] || '30';
    const persentilJual = bagian[3] || '0.3';
    const persentilBeli = bagian[4] || '0.5';
    aksi = 'analisis_range_pagi_sore';
    url = `${SCALPING_URL}/v1/analisis/range-pagi-sore/${ticker}?window_hari=${windowHari}&persentil_jual=${persentilJual}&persentil_beli=${persentilBeli}`;
  } else {
    aksi = 'analisis_swing';
    url = `${BASE_URL}/v1/analisis/swing/${ticker}`;
  }
}

return [{
  json: {
    valid: true,
    aksi,
    url,
    ticker,
    from: nomorPengirim
  }
}];

// === FORMAT HASIL API JADI TEKS WA (dengan split otomatis batas karakter) ===
const rawInput = $input.first().json;
// Menangani jika input berupa Array [...] atau Object {...}
const inputHttp = Array.isArray(rawInput) ? rawInput[0] : rawInput;

const konteks = $('Parse Perintah Scan').item.json;
const aksi = konteks.aksi;
const ticker = konteks.ticker;
const from = konteks.from;

// Batas aman WhatsApp: pesan text maksimal 4096 karakter -> pakai 4000.
const BATAS_KARAKTER_WA = 4000;

// Pecah pesan panjang menjadi beberapa chunk, potong di baris baru terdekat.
function splitPesan(pesan, batas = BATAS_KARAKTER_WA) {
  if (pesan.length <= batas) return [pesan];
  const hasil = [];
  let sisa = pesan;
  while (sisa.length > batas) {
    let potong = sisa.lastIndexOf('\n', batas);
    if (potong <= 0) potong = batas;
    hasil.push(sisa.slice(0, potong));
    sisa = sisa.slice(potong);
  }
  if (sisa.length > 0) hasil.push(sisa);
  return hasil;
}

const gagal = !inputHttp || Boolean(inputHttp.error) || inputHttp.status !== 'success';

if (gagal) {
  const detailError = inputHttp?.detail || inputHttp?.error || 'Server tidak merespons dengan benar.';
  const pesan = `⚠️ *Gagal memproses permintaan*${ticker ? ' untuk *' + ticker + '*' : ''}.\n${detailError}\n\nCek lagi kode saham atau format perintahnya ya.`;
  return [{ json: { pesan_wa: pesan, to: from } }];
}

function rp(angka) {
  if (angka === undefined || angka === null || angka === '') return 'N/A';
  return `Rp${Number(angka).toLocaleString('id-ID')}`;
}

function fmtAngka(angka) {
  if (angka === undefined || angka === null || angka === '') return '-';
  return Number(angka).toLocaleString('id-ID');
}

function formatSwing(data) {
  let t = `📊 *ANALISIS SWING - ${data.saham}*\n`;
  t += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  t += `💰 *Harga Saat Ini:* ${rp(data.harga_saat_ini)}\n`;
  t += `🎯 *Rekomendasi Akhir:* *${data.rekomendasi_akhir}*\n\n`;

  // --- FUNDAMENTAL & DIVIDEN ---
  if (data.fundamental) {
    const f = data.fundamental;
    t += `🏢 *FUNDAMENTAL*\n`;
    t += `• Harga Wajar: ${rp(f.harga_wajar)}\n`;
    t += `• Maks Layak Beli: ${rp(f.harga_maks_layak_beli)}\n`;
    if (f.status_harga_wajar) t += `• Status Wajar: ${f.status_harga_wajar}\n`;
    if (data.premi_terhadap_harga_wajar_persen !== undefined && data.premi_terhadap_harga_wajar_persen !== null) {
      const premi = data.premi_terhadap_harga_wajar_persen;
      t += `• Premi/Diskon Wajar: ${premi > 0 ? '+' : ''}${premi}%\n`;
    }
    if (f.pbv_ratio) t += `• PBV Ratio: ${f.pbv_ratio}x\n`;
    if (f.return_on_equity) t += `• ROE: ${f.return_on_equity}\n`;
    t += `• Status Dividen: ${f.status_dividen}\n`;

    if (f.info_tanggal_dividen && f.info_tanggal_dividen.tersedia) {
      const div = f.info_tanggal_dividen;
      t += `  ├ Est. Cum-Date: ${div.estimasi_cum_date || '-'}\n`;
      t += `  ├ Ex-Date: ${div.ex_dividend_date || '-'}\n`;
      t += `  └ _${div.catatan}_\n`;
    }
    if (data.peringatan_valuasi) {
      t += `⚠️ *Peringatan Valuasi:* ${data.peringatan_valuasi}\n`;
    }
    t += `\n`;
  }

  // --- TEKNIKAL & BANDARMOLOGI ---
  if (data.teknikal) {
    const tek = data.teknikal;
    t += `📈 *TEKNIKAL & ARUS MODAL*\n`;
    t += `• Status Tren: ${tek.status_tren}\n`;
    t += `• Support/Lantai: ${tek.klasifikasi_lantai}\n`;
    t += `• Target Resisten: ${tek.target_atap_resisten}\n`;
    if (tek.status_arus_modal) t += `• Arus Kas: ${tek.status_arus_modal}\n`;

    if (tek.arus_bandar_cmf) {
      const cmf = tek.arus_bandar_cmf;
      t += `• Arus Bandar CMF: ${cmf.status} (Score: ${cmf.cmf_20})\n`;
      if (cmf.penjelasan) t += `  └ _${cmf.penjelasan}_\n`;
    }

    if (tek.ema20) t += `• Moving Average: EMA20 (${tek.ema20}) | EMA50 (${tek.ema50}) | EMA200 (${tek.ema200})\n`;

    let indList = [];
    if (tek.rsi_14 !== undefined) indList.push(`RSI(14): ${tek.rsi_14}`);
    if (tek.stochastic_d !== undefined) indList.push(`Stoch D: ${tek.stochastic_d}`);
    if (tek.adx_strength !== undefined) indList.push(`ADX: ${tek.adx_strength}`);
    if (indList.length > 0) t += `• Oscillation: ${indList.join(' | ')}\n`;

    if (tek.plus_di_14 !== undefined && tek.minus_di_14 !== undefined) {
      t += `• Directional Index: DI+ (${tek.plus_di_14}) | DI- (${tek.minus_di_14})\n`;
    }

    if (tek.macd !== undefined) {
      t += `• MACD: ${tek.macd} (Signal: ${tek.macd_signal} | Hist: ${tek.macd_histogram})\n`;
    }

    t += `• Oversold Swing: ${tek.konfirmasi_oversold_swing}\n`;
    t += `• Daytrading ADX: ${tek.konfirmasi_daytrading_adx}\n`;

    if (tek.rekomendasi_daytrading) {
      const dt = tek.rekomendasi_daytrading;
      if (dt.aktif) {
        t += `\n🚀 *REKOMENDASI DAYTRADING / FAST TRADE*\n`;
        t += `• Kekuatan Tren: ${dt.kualitas_tren_adx?.kekuatan || '-'}\n`;
        t += `• Entry Terbaik: ${rp(dt.harga_entry_terbaik)}\n`;
        t += `• Masuk Maksimal: ${rp(dt.harga_masuk_maksimal)}\n`;
        t += `• Target Jual: ${rp(dt.target_jual)} (${dt.estimasi_profit_bersih_dari_entry_terbaik_persen}% est. profit)\n`;
        t += `• Stop Loss (SL): ${rp(dt.stop_loss_disarankan)}\n`;
        if (dt.catatan_horizon) t += `⏱️ _${dt.catatan_horizon}_\n`;
        if (dt.keterangan) t += `ℹ️ _${dt.keterangan}_\n`;
      }
    }

    if (tek.penjelasan_indikator) {
      const pi = tek.penjelasan_indikator;
      t += `\n🔍 *Rincian Indikator:*\n`;
      if (pi.rsi) t += `• ${pi.rsi}\n`;
      if (pi.stochastic) t += `• ${pi.stochastic}\n`;
      if (pi.macd) t += `• ${pi.macd}\n`;
      if (pi.adx) t += `• ${pi.adx}\n`;
      if (pi.posisi_ema) t += `• ${pi.posisi_ema}\n`;
      if (pi.volume) t += `• ${pi.volume}\n`;
      if (pi.arus_bandar) t += `• ${pi.arus_bandar}\n`;
    }

    if (tek.penjelasan_chart) t += `\n📝 *Analisis Chart:*\n_${tek.penjelasan_chart}_\n`;
  }

  // --- RISIKO & GUARDRAIL ---
  if (data.guardrail_proteksi || data.guardrail_fundamental) {
    t += `\n🛡️ *RISIKO & GUARDRAIL*\n`;
    if (data.guardrail_proteksi) {
      const g = data.guardrail_proteksi;
      t += `• Kategori Risiko: ${g.kategori_risiko}\n`;
      if (g.aturan_akun) t += `• Aturan Akun: ${g.aturan_akun}\n`;
      t += `• Wajib Stop Loss: ${g.wajib_stop_loss ? 'Ya 🛑' : 'Tidak 🟢'}\n`;
    }

    if (data.guardrail_fundamental) {
      const gf = data.guardrail_fundamental;
      t += `• Aman Avg Down: ${gf.aman_untuk_average_down ? 'YA ✅' : 'TIDAK ❌'}\n`;
      if (gf.alasan && gf.alasan.length > 0) {
        t += `⚠️ *Alasan Guardrail:* ${gf.alasan.join('; ')}\n`;
      }
    }
  }

  // --- ZONA AVERAGE DOWN ---
  if (data.zona_average_down && (data.zona_average_down.tersedia === undefined || data.zona_average_down.tersedia === true)) {
    const z = data.zona_average_down;
    t += `\n🎯 *ZONA AVERAGE DOWN*\n`;
    if (z.tranche_1) t += `1️⃣ *Tranche 1 (${z.tranche_1.alokasi_persen}%):* ${rp(z.tranche_1.area_harga)} (${z.tranche_1.keterangan})\n`;
    if (z.tranche_2) t += `2️⃣ *Tranche 2 (${z.tranche_2.alokasi_persen}%):* ${rp(z.tranche_2.area_harga)} (${z.tranche_2.keterangan})\n`;
    if (z.tranche_3) t += `3️⃣ *Tranche 3 (${z.tranche_3.alokasi_persen}%):* ${rp(z.tranche_3.area_harga)} (${z.tranche_3.keterangan})\n`;
    if (z.catatan) t += `ℹ️ _${z.catatan}_\n`;
  }

  // --- MANAJEMEN RISIKO ---
  if (data.manajemen_risiko) {
    t += `\n💼 *MANAJEMEN RISIKO*\n`;
    t += `• Maks Alokasi: ${data.manajemen_risiko.maks_alokasi_modal_persen}% dari total modal\n`;
    if (data.manajemen_risiko.keterangan) {
      t += `ℹ️ _${data.manajemen_risiko.keterangan}_\n`;
    }
  }

  // --- PANDUAN STRATEGI ---
  if (data.teknikal?.panduan_saran_growin) {
    t += `\n💡 *PANDUAN STRATEGI:*\n${data.teknikal.panduan_saran_growin}\n`;
  }

  // --- KONDISI MARKET (IHSG) ---
  if (data.kondisi_market) {
    t += `\n🌏 *Kondisi IHSG:* ${data.kondisi_market.status} (${data.kondisi_market.ihsg_saat_ini})`;
  }

  return [t];
}

