  }

  t += `📈 *PERINGKAT 6 STRATEGI:*\n`;
  (data.peringkat_strategi || []).forEach((p, i) => {
    t += `${i + 1}. *${p.nama}* — skor ${p.skor}/100 ${p.kecocokan || ''}\n`;
    t += `   Sinyal: ${p.sinyal_aktif ? '✅ aktif' : '⚪ tidak aktif'}\n`;
    if (p.rekomendasi_aksi) t += `   → ${p.rekomendasi_aksi}\n`;
