// REKOMENDASI PER SEKTOR: saham terbaik per strategi dalam 1 sektor
function formatRekomendasiSektor(res) {
  const d = res.data || res;
  let header = `🏭 *REKOMENDASI SEKTOR: ${d.kata_kunci || ''}*\n`;
  header += `━━━━━━━━━━━━━━━━━━━━\n`;
  // Jangan pakai `|| '-'` untuk angka — 0 akan salah tampil sebagai '-'.
  const fmtN = (v) => (v === undefined || v === null ? '-' : v);
  header += `Saham di sektor: ${fmtN(d.jumlah_saham_di_sektor)} | Diskor: ${fmtN(d.jumlah_saham_diskor)} | Berhasil: ${fmtN(d.jumlah_saham_berhasil)}\n`;
  if (d.peringatan) header += `⚠️ _${d.peringatan}_\n`;
  if (d.keterangan_batas) header += `⚠️ _${d.keterangan_batas}_\n`;

  const messages = [];
  let current = header + `\n`;

  (d.leaderboard_per_strategi || []).forEach((lb) => {
    let blok = `━━━━━━━━━━━━━━━━━━━━\n📌 *${lb.nama}*\n`;
    if (!lb.terbaik || lb.terbaik.length === 0) {
      blok += `(tidak ada saham ber-skor untuk strategi ini)\n\n`;
    } else {
      lb.terbaik.forEach((f, i) => {
        blok += `${i + 1}. *${f.ticker}* — skor ${f.skor}/100 ${f.kecocokan || ''}\n`;
        blok += `   Harga ${rp(f.harga)} | Sinyal: ${f.sinyal_aktif ? '✅ aktif' : '⚪ tidak aktif'}\n`;
        if (f.backtest) {
          const bt = f.backtest;
          blok += `   📉 Backtest: ${bt.satuan_metrik_asli} = ${bt.metrik_asli_persen}% (${bt.metrik_per_hari_persen}%/hari) | sample ${bt.sample} | ${bt.andal ? '✅ ANDAL' : '⚠️ sampel kecil'}\n`;
        }
        blok += `\n`;
      });
    }

    // Jika blok ini membuat pesan melebihi batas, mulai pesan baru
    if ((current.length + blok.length) > BATAS_KARAKTER_WA) {
      messages.push(current.trim());
      current = `🏭 *Lanjutan Rekomendasi ${d.kata_kunci || ''}*\n\n` + blok;
    } else {
      current += blok;
    }
  });

  messages.push(current.trim());
  return messages;
}

