  let t = `✅ *VALIDASI STRATEGI - ${data.saham}*\n`;
  t += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  t += `💰 Harga: ${rp(data.harga_saat_ini)}\n`;
  t += `🏆 Terbaik versi *SKOR*: *${data.strategi_terbaik_versi_skor || '-'}*\n`;
  t += `📉 Terbaik versi *BACKTEST*: *${data.strategi_terbaik_versi_backtest || '-'}*\n`;
  t += `✅ Cocok Top-1: ${data.cocok_top1 ? 'YA 🎯' : 'TIDAK'}\n`;
  if (data.tumpang_tindih_top3 !== undefined) t += `🔁 Tumpang tindih Top-3: ${data.tumpang_tindih_top3}/3\n`;
  if (data.korelasi_spearman_skor_vs_backtest !== undefined && data.korelasi_spearman_skor_vs_backtest !== null) {
    t += `📊 Korelasi Spearman: ${data.korelasi_spearman_skor_vs_backtest}\n`;
  }
  t += `\n`;

  t += `📈 *PERINGKAT SKOR:*\n`;
  (data.peringkat_skor || []).forEach((p, i) => {
    t += `${i + 1}. ${p.nama} — ${p.skor}/100 ${p.kecocokan || ''}${p.sinyal_aktif ? ' ✅' : ''}\n`;
  });
  t += `\n`;

  t += `📉 *PERINGKAT BACKTEST (per hari):*\n`;
  (data.peringkat_backtest || []).forEach((h, i) => {
    t += `${i + 1}. ${h.nama} — ${h.metrik_per_hari_persen}%/hari (${h.satuan_metrik_asli}: ${h.metrik_asli_persen}%) | sample ${h.sample} ${h.andal ? '✅' : '⚠️ kecil'}\n`;
  });
  t += `\n`;

  if (data.catatan && data.catatan.length) {
    t += `📝 *CATATAN:*\n`;
    data.catatan.forEach(c => t += `• ${c}\n`);
  }

  return [t];
}

function formatScreenerSwing(res) {
