function formatScreenerScalping(res) {
  let messages = [];
  let header = `⚡ *SCREENER SCALPING (FAST INTRADAY)*\n`;

  if (res.peringatan) {
    header += `⚠️ *${res.peringatan}*\n\n`;
  }

  if (res.diproses_offset !== undefined || res.diproses_limit !== undefined) {
    header += `Batch: Offset ${res.diproses_offset || 0} | Limit ${res.diproses_limit || 0}\n`;
  }

  if (res.total_saham_di_daftar_bei) {
    header += `Total Saham Terdaftar BEI: ${res.total_saham_di_daftar_bei}\n`;
  }

  if (res.offset_berikutnya) {
    header += `\n👉 _Ketik *scan screener scalping ${res.offset_berikutnya} ${res.diproses_limit}* untuk batch selanjutnya._\n\n`;
  } else {
    header += `\n\n`;
  }

  const list = res.radar_saham_fast_intraday_aktif || [];

  if (list.length === 0) {
    header += 'Tidak ada saham yang lolos filter scalping pada batch ini.\n\n';
    messages.push(header.trim());
  } else {
    let currentMessage = header;

    list.forEach((s) => {
      let t = `━━━━━━━━━━━━━━━━━━━━\n`;
      t += `*${s.saham}*\n`;
      t += `🚦 Status: ${s.status || '-'}\n\n`;

      t += `📈 *INDIKATOR MOMENTUM (15M)*\n`;
      t += `• RSI Momentum: ${s.rsi_momentum}\n`;
      t += `• ADX Power: ${s.adx_power}\n`;

      if (s.kualitas_tren_adx) {
        t += `• Tren ADX: ${s.kualitas_tren_adx.kekuatan}\n`;
        t += `• Arah Tren: ${s.kualitas_tren_adx.arah}\n`;
      }

      if (s.arus_bandar_cmf) {
        t += `• CMF: ${s.arus_bandar_cmf.status} (Score: ${s.arus_bandar_cmf.cmf_20})\n`;
        if (s.arus_bandar_cmf.penjelasan) {
          t += `  └ _${s.arus_bandar_cmf.penjelasan}_\n`;
        }
      }
      t += `\n`;

      if (s.rekomendasi_entry_daytrading && s.rekomendasi_entry_daytrading.aktif) {
        const dt = s.rekomendasi_entry_daytrading;
        t += `🚀 *REKOMENDASI ENTRY*\n`;
        t += `• Entry Terbaik: ${rp(dt.harga_entry_terbaik)}\n`;
        t += `• Masuk Maks: ${rp(dt.harga_masuk_maksimal)}\n`;
        t += `• Target Jual (TP): ${rp(dt.target_jual)} (${dt.estimasi_profit_bersih_dari_entry_terbaik_persen}% est. profit)\n`;
        t += `• Stop Loss (SL): ${rp(dt.stop_loss_disarankan)} (${dt.estimasi_rugi_ke_sl_dari_entry_terbaik_persen}%)\n`;
        if (dt.rasio_risk_reward) t += `• Rasio Risk/Reward: ${dt.rasio_risk_reward}\n`;
        if (dt.keterangan) t += `ℹ️ _${dt.keterangan}_\n`;
        if (dt.asumsi) t += `📌 _${dt.asumsi}_\n`;
        t += `\n`;
      }

      if (s.bracket_order_growin) {
        const b = s.bracket_order_growin;
        t += `🎯 *BRACKET ORDER*\n`;
        t += `🟢 Target TP: ${rp(b.target_take_profit)}\n`;
        t += `🔴 Batas Cut Loss: ${rp(b.batas_cut_loss)}\n`;
        if (b.maks_hold_bar_disarankan) {
          t += `⏱️ Maks Hold Bar: ${b.maks_hold_bar_disarankan} bar\n`;
        }
        t += `📐 Metode: ${b.metode}\n\n`;
      }

      if (s.rekomendasi) {
        t += `💡 *KESIMPULAN:*\n_${s.rekomendasi}_\n\n`;
      }

      if ((currentMessage.length + t.length) > BATAS_KARAKTER_WA) {
        messages.push(currentMessage.trim());
        currentMessage = `⚡ *Lanjutan Screener Scalping (Bag. ${messages.length + 1})*\n\n` + t;
      } else {
        currentMessage += t;
      }
    });

    if (res.saham_gagal_dianalisis && res.saham_gagal_dianalisis.length > 0) {
      let fT = `━━━━━━━━━━━━━━━━━━━━\n⚠️ *Saham Gagal Dianalisis:*\n${res.saham_gagal_dianalisis.join(', ')}\n`;
      if ((currentMessage.length + fT.length) > BATAS_KARAKTER_WA) {
        messages.push(currentMessage.trim());
        currentMessage = `⚡ *Lanjutan Screener Scalping (Bag. ${messages.length + 1})*\n\n` + fT;
      } else {
        currentMessage += fT;
      }
    }

    if (currentMessage.trim().length > 0) {
      messages.push(currentMessage.trim());
    }
  }

  return messages;
}

function formatBacktest(data) {
  if (!data || !data.total_transaksi) {
    return [`📉 *Backtest ${data?.saham || ''}*\n${data?.keterangan || 'Tidak ada sinyal pada periode ini.'}`];
  }
  let t = `📉 *Backtest ${data.strategi} - ${data.saham}*\n`;
  t += `Total transaksi: ${data.total_transaksi}\n`;
  t += `Win rate: ${data.win_rate_persen}%\n`;
  t += `Rata-rata return/transaksi: ${data.rata_rata_return_per_transaksi_persen}%\n`;
  t += `Total return gabungan: ${data.total_return_gabungan_persen}%\n`;
  t += `Max drawdown: ${data.max_drawdown_persen}%\n\n`;
  t += `ℹ️ ${data.catatan}`;
  return [t];
}

