function formatMarket(data) {
  let t = `🌏 *Kondisi Market (IHSG)*\n`;
  t += `Status: ${data.status}\n`;
  if (data.ihsg_saat_ini) t += `IHSG saat ini: ${data.ihsg_saat_ini}\n`;
  if (data.ihsg_ema50) t += `EMA50: ${data.ihsg_ema50}\n`;
  if (data.keterangan) t += `${data.keterangan}\n`;
  return [t];
}
function formatJumlah(n) {
  if (n === null || n === undefined) return '-';
  if (n >= 1e9) return (n / 1e9).toFixed(2) + ' M';
  if (n >= 1e6) return (n / 1e6).toFixed(1) + ' jt';
  if (n >= 1e3) return (n / 1e3).toFixed(0) + ' rb';
  return String(n);
}

function splitPesan(teks) {
  // Pecah teks panjang jadi beberapa pesan WA — batas aman ~3500 karakter/pesan.
  const LIMIT = 3500;
  const hasil = [];
  let sisa = (teks || '').trim();
  let bagian = 1;
  while (sisa.length > LIMIT) {
    let potong = sisa.lastIndexOf('\n', LIMIT);
    if (potong < 0) potong = LIMIT;
    hasil.push(sisa.slice(0, potong).trim());
    sisa = sisa.slice(potong).trim();
    bagian++;
    if (bagian > 25) break;
  }
  if (sisa.length > 0) hasil.push(sisa.trim());
  return hasil.length > 0 ? hasil : [''];
}

function formatPasar(data) {
  const ikon = { gainer: '🚀', loser: '📉', value: '💎' }[data.jenis] || '🔥';
  let t = `${ikon} *${data.label || 'Pasar'}*${data.tanggal_data ? ` (per ${data.tanggal_data})` : ''}\n`;
  t += `━━━━━━━━━━━━━━━━━━━━\n`;
  t += `Analisis: ${data.jumlah_saham_dianalisis} saham BEI\n\n`;
  const list = data.list || [];
  if (list.length === 0) {
    t += 'Tidak ada data untuk kategori ini.';
    return [t];
  }
  list.forEach((m, i) => {
    const pct = (m.pct_change_hari !== null && m.pct_change_hari !== undefined)
      ? `${m.pct_change_hari > 0 ? '+' : ''}${m.pct_change_hari}%` : '-';
    t += `${i + 1}. *${m.ticker}* — ${rp(m.harga)} (${pct})\n`;
    t += `   Vol: ${formatJumlah(m.volume)} | Nilai: Rp${(m.nilai_transaksi / 1e9).toFixed(1)} M\n`;
    if (m.pct_change_5d !== null && m.pct_change_5d !== undefined) {
      t += `   5d: ${m.pct_change_5d > 0 ? '+' : ''}${m.pct_change_5d}%\n`;
    }
  });
  if (data.jenis === 'gainer') {
    t += `\n⚠️ *Catatan:* Top gainer cenderung reversal (profit-taking) — JANGAN dipakai sebagai sinyal beli langsung.`;
  }
  return splitPesan(t);
}

function formatRekomendasiIntraday(data) {
  let t = `⚡ *REKOMENDASI INTRADAY*${data.tanggal_data ? ` (per ${data.tanggal_data})` : ''}\n`;
  t += `━━━━━━━━━━━━━━━━━━━━\n`;
  t += `Filter: *${(data.filter && data.filter.label) || 'Most Active'}* — likuiditas saja, arah tetap dari sinyal strategi\n`;
  t += `Kandidat: ${data.jumlah_saham_berhasil}/${data.jumlah_saham_diproses} berhasil dianalisis\n`;
  if (data.saham_gagal && data.saham_gagal.length > 0) {
    t += `Gagal: ${data.saham_gagal.slice(0, 5).join(', ')}${data.saham_gagal.length > 5 ? '...' : ''}\n`;
  }
  t += `\n`;
  if (data.kandidat && data.kandidat.length > 0) {
    t += `🎯 *KANDIDAT LIKUID:*\n`;
    data.kandidat.forEach((k, i) => {
      const pct = (k.pct_change_hari !== null && k.pct_change_hari !== undefined) ? `${k.pct_change_hari > 0 ? '+' : ''}${k.pct_change_hari}%` : '-';
      t += `${i + 1}. *${k.ticker}* — ${rp(k.harga)} (${pct}) | Nilai Rp${k.nilai_transaksi_miliar} M\n`;
    });
    t += `\n`;
  }
  const lbs = data.leaderboard_per_strategi_intraday || [];
  let ada = false;
  lbs.forEach((lb) => {
    if (!lb.terbaik || lb.terbaik.length === 0) return;
    ada = true;
    t += `📌 *${lb.nama}*\n`;
    lb.terbaik.forEach((f, i) => {
      let baris = `${i + 1}. *${f.ticker}* — skor ${f.skor} | ${f.kecocokan}`;
      if (f.sinyal_aktif) baris += ` | Sinyal: ${f.sinyal_aktif}`;
      if (f.harga) baris += ` | Harga: ${rp(f.harga)}`;
      t += baris + `\n`;
    });
    t += `\n`;
  });
  if (!ada) {
    t += `(belum ada saham ber-skor untuk strategi intraday — coba n lebih besar)\n\n`;
  }
  t += `💡 *Lanjutkan analisis detail:* ketik *scan [TICKER] bpjs*, *scan [TICKER] beli-pagi*, atau *scan [TICKER] scalping*.\n`;
  if (data.peringatan) t += `⚠️ *${data.peringatan}*\n`;
  return splitPesan(t);
}

let arrayPesan = [];
const data = inputHttp.data || inputHttp;

try {
  if (aksi === 'analisis_swing') arrayPesan = formatSwing(data);
