  else if (aksi === 'analisis_strategi_gabungan') arrayPesan = formatStrategiGabungan(data);
  else if (aksi === 'rekomendasi_sektor') arrayPesan = formatRekomendasiSektor(inputHttp);
  else if (aksi === 'validasi_strategi') arrayPesan = formatValidasiStrategi(data);
  else if (aksi === 'screener_swing') arrayPesan = formatScreenerSwing(inputHttp);
  else if (aksi === 'screener_gorengan') arrayPesan = formatScreenerGorengan(inputHttp);
  else if (aksi === 'screener_scalping') arrayPesan = formatScreenerScalping(inputHttp);
  else if (aksi === 'backtest_swing' || aksi === 'backtest_gorengan') arrayPesan = formatBacktest(data);
  else if (aksi === 'backtest_bpjs') arrayPesan = formatBacktestBPJS(data);
  else if (aksi === 'pasar_active' || aksi === 'pasar_value' || aksi === 'pasar_gainer' || aksi === 'pasar_loser') arrayPesan = formatPasar(data);
  else if (aksi === 'rekomendasi_intraday') arrayPesan = formatRekomendasiIntraday(data);
