const konteks = $('Parse Perintah Scan').item.json;
const BATAS_KARAKTER_WA = 4000;
function splitPesan(pesan, batas = BATAS_KARAKTER_WA) {
  if (pesan.length <= batas) return [pesan];
  const hasil = [];
  let sisa = pesan;
  while (sisa.length > batas) {
    let potong = sisa.lastIndexOf('\n', batas);
    if (potong <= 0) potong = batas;
    hasil.push(sisa.slice(0, potong));
    sisa = sisa.slice(potong);
  }
  if (sisa.length > 0) hasil.push(sisa);
  return hasil;
}
const pesan = `❓ ${konteks.alasan}`;
return splitPesan(pesan).map(p => ({ json: { pesan_wa: p, to: konteks.from } }));
